help_body <- function(title) {
  t <- help_topics[[title]]
  if (is.null(t)) return(shiny::markdown("No help is written for this screen yet. See **Help** in the top bar for the getting-started guide."))
  shiny::tagList(
    shiny::tags$h6(class = "fw-bold", "What it does"), shiny::markdown(t$what),
    shiny::tags$h6(class = "fw-bold", "Data you need"), shiny::markdown(t$data),
    shiny::tags$h6(class = "fw-bold", "Reading the results"), shiny::markdown(t$read),
    if (!is.null(t$tips)) shiny::tagList(shiny::tags$h6(class = "fw-bold", "Tips"), shiny::markdown(t$tips)))
}

help_modal <- function(title) shiny::modalDialog(title = paste("Help:", title), help_body(title), easyClose = TRUE, size = "l",
                                                 footer = shiny::modalButton("Close"))

# Browser side: the Help button sends the title of the screen being shown.
help_js <- "
$(document).on('click', '#help_btn', function(e) {
  e.preventDefault();
  var link = $('.navbar .dropdown-item.active, .navbar .nav-link.active').not('.dropdown-toggle').last();
  Shiny.setInputValue('help_request', link.text().trim(), {priority: 'event'});
});
"
